UPDATE risk_knowledge_entries SET problem_json='{"statement":"Hidden buttons do not stop a low-privilege caller from invoking privileged APIs directly.","customer_symptom":"A user or operator may observe hidden buttons do not stop a low-privilege caller from invoking privileged apis directly; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An authenticated low-privilege caller can bypass interface-only restrictions and invoke privileged API routes or service methods directly when server-side authorization is missing, inconsistent or fails open.","affected_assets":["privileged API functions and service methods","role-to-function authorization rules","administrative resources and tenant state","audit records and downstream actions"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-role platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The boundary between a caller''s authenticated role and server-enforced permission to perform a protected function in the assessed tenant.","operational_impact":"If hidden buttons do not stop a low-privilege caller from invoking privileged apis directly, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}',review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-023 role, permission, route, service-method or authorization-policy change","ARL-KB-023 new privileged function or alternate execution path","ARL-KB-023 function-level authorization bypass or fail-open incident","ARL-KB-023 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; customer and independent practitioner validation required"}',content_digest='f3a6d7cb7c0caa202a6aca960f4aa73b060ad63cc65f3788da17dcb8836b7a22',updated_at='2026-10-09' WHERE id='ARL-KB-023';
UPDATE risk_knowledge_checks SET objective='Determine whether every sensitive API and service function enforces the approved role-to-function authorization server-side, including direct calls, alternate methods and policy failures.',required_evidence_json='["ARL-KB-023 exact assessed system, version, environment, tenant, role and protected function scope","ARL-KB-023 organisation-approved role-function authorization matrix with accountable owner and privileged operations","ARL-KB-023 source or configuration evidence of server-side authorization checks and fail-closed policy paths","ARL-KB-023 bounded positive evidence of authorised role performing the approved function with observed policy decision","ARL-KB-023 bounded negative evidence of low-privilege direct API, alternate-method and missing-policy attempts rejected before side effects","ARL-KB-023 observed runtime authorization and downstream audit events proving tested allow and deny outcomes","ARL-KB-023 tester and reviewer identity, role, timestamp, exact version and evidence digest"]',pass_condition='KB-023 passes only when the assessed role-function matrix and source enforcement apply to the exact version, authorised actions work within scope, low-privilege direct/alternate API calls and fail-open variants are denied before any side effect, observed authorization/audit events support each claim, and accountable human review records remaining limitations.',fail_condition='KB-023 fails or requires review when a low-privilege identity invokes a protected function directly or through alternate routes, when server-side authorization is absent or fails open, or when required scoped policy, observed denial and human-review evidence is missing.',content_digest='8b0d1f8cf0ab2a3899305684f23a051940bca69be7ebc9a4a12dfe3276ee101e',updated_at='2026-10-09' WHERE entry_id='ARL-KB-023';
